namespace ActivityService.Endpoints;

internal static class ActivityEndpointHelpers
{
    internal static bool CanReviewAllActivities(
        ClaimsPrincipal user)
    {
        return user.IsInRole(AuthRoles.Admin)
            || user.IsInRole(AuthRoles.StudentAffairsAdmin);
    }

    internal static ActivityResponse ToResponse(
        ClubActivity activity, int? visibleUserId = null)
    {
        return new ActivityResponse(
            activity.Id,
            activity.ClubId,
            activity.ClubName,
            activity.Title,
            activity.Description,
            activity.StartTimeUtc,
            activity.EndTimeUtc,
            GetMeetingDays(activity.MeetingDaysCsv),
            activity.Location,
            activity.Status,
            activity.CreatedByUserId,
            activity.CreatedAtUtc,
            activity.Participants
                .Where(x => visibleUserId == null || x.UserId == visibleUserId)
                .OrderBy(x => x.RegisteredAtUtc)
                .Select(x => new ActivityParticipantResponse(
                    x.Id,
                    x.UserId,
                    x.FullName,
                    x.AttendanceStatus,
                    x.RegisteredAtUtc))
                .ToArray(),
            activity.Attendances
                .Where(x => visibleUserId == null || x.UserId == visibleUserId)
                .OrderByDescending(x => x.AttendanceDate)
                .ThenBy(x => x.FullName)
                .Select(x => new ActivityAttendanceResponse(
                    x.Id,
                    x.UserId,
                    x.FullName,
                    x.AttendanceDate,
                    x.Status,
                    x.Note,
                    x.CheckedInAtUtc,
                    x.CheckedInByUserId)
                {
                    SessionId = x.SessionId,
                    Version = x.Version,
                    VerificationStatus = x.VerificationStatus,
                    VerificationMethod = x.VerificationMethod,
                    RecognitionStatus = x.RecognitionStatus,
                    ContributionId = x.ContributionId
                })
                .ToArray())
        {
            Version = activity.Version,
            IsInternal = activity.IsInternal,
            PublicationStatus = activity.PublicationStatus,
            DiscoveryVisibility = activity.DiscoveryVisibility,
            SemesterId = activity.SemesterId,
            Capacity = activity.Capacity,
            RegistrationOpensAt = activity.RegistrationOpensAt,
            RegistrationClosesAt = activity.RegistrationClosesAt,
            Eligibility = activity.IsInternal ? "CLUB_MEMBER" : "CAMPUS_PUBLIC",
            CoverImageUrl = activity.CoverImageUrl,
            RegisteredCount = activity.Participants.Count,
            VerifiedAttendanceCount = activity.Attendances.Count(x => x.VerificationStatus == "VERIFIED"),
            EffortTier = activity.EffortTier,
            Scale = activity.Scale,
            PolicyVersion = activity.PolicyVersion,
            EvidenceRequirements = activity.EvidenceRequirements,
            PillarWeights = JsonSerializer.Deserialize<List<PillarWeight>>(activity.PillarWeightsJson, ActivitySessionEndpoints.JsonOptions) ?? []
        };
    }

    internal static IReadOnlyList<int> NormalizeMeetingDays(
        IEnumerable<int>? meetingDays)
    {
        return meetingDays?
            .Where(day => day is >= 1 and <= 7)
            .Distinct()
            .OrderBy(day => day)
            .ToArray()
            ?? [];
    }

    internal static IReadOnlyList<int> GetMeetingDays(
        string? meetingDaysCsv)
    {
        if (string.IsNullOrWhiteSpace(meetingDaysCsv))
        {
            return [];
        }

        return NormalizeMeetingDays(
            meetingDaysCsv
                .Split(
                    ',',
                    StringSplitOptions.RemoveEmptyEntries
                    | StringSplitOptions.TrimEntries)
                .Select(value =>
                    int.TryParse(value, out var day)
                        ? day
                        : 0));
    }

    internal static async Task<bool> CanManageClubAsync(
        int clubId,
        ClubAccessClient clubAccess,
        HttpContext httpContext,
        CancellationToken cancellationToken,
        bool bypassCache = false)
    {
        var access = await clubAccess.GetMyAccessAsync(
            httpContext.GetBearerToken(),
            cancellationToken,
            bypassCache);

        return access.Any(
            x => x.ClubId == clubId && x.CanManage);
    }

    internal static async Task<bool> CanManageClubOrReviewAllAsync(
        int clubId,
        ClaimsPrincipal user,
        ClubAccessClient clubAccess,
        HttpContext httpContext,
        CancellationToken cancellationToken,
        bool bypassCache = false)
    {
        return CanReviewAllActivities(user)
            || await CanManageClubAsync(
                clubId,
                clubAccess,
                httpContext,
                cancellationToken,
                bypassCache);
    }

    internal static string? ValidateAttendance(
        string? status,
        string? note)
    {
        return AttendanceManagementRules.ValidateEntry(
            status,
            note);
    }

    internal static void ApplyAttendance(
        ActivityAttendance row,
        string status,
        string? note,
        int checkedByUserId,
        DateTimeOffset activityStartTimeUtc)
    {
        row.Status = status;

        row.Note = string.IsNullOrWhiteSpace(note)
            ? null
            : note.Trim();

        row.UpdatedAtUtc = DateTimeOffset.UtcNow;

        if (status == AttendanceStatuses.NotMarked)
        {
            row.CheckedInAtUtc = null;
            row.CheckedInByUserId = null;
            return;
        }

        row.CheckedInByUserId = checkedByUserId;

        row.CheckedInAtUtc =
            DateTimeOffset.UtcNow >= activityStartTimeUtc
                ? DateTimeOffset.UtcNow
                : null;
    }
}

